1	// Package review — see env.go for package-level rationale.
2	//
3	// tui_model.go provides reviewTUIModel, the Bubble Tea Model for the
4	// review dashboard. The model renders a per-agent status table
5	// during the run and supports Ctrl+O drill-in mode for inspecting one agent's
6	// live event buffer on the alt screen.
7	package review
8	
9	import (
10		"context"
11		"fmt"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16	
17		"charm.land/bubbles/v2/spinner"
18		tea "charm.land/bubbletea/v2"
19		"charm.land/lipgloss/v2"
20	
21		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
22		"github.com/entireio/cli/cmd/entire/cli/stringutil"
23	)
24	
25	// agentRow holds per-agent live state during the TUI run.
26	type agentRow struct {
27		name     string
28		status   reviewtypes.AgentStatus
29		runStart time.Time          // stamped on first event from this agent
30		runEnd   time.Time          // stamped on Finished/RunError event
31		tokens   reviewtypes.Tokens // cumulative
32		preview  string             // latest AssistantText preview, capped by display width
33		buffer   []reviewtypes.Event
34		err      error
35	}
36	
37	// agentEventMsg is sent to the Bubble Tea program when an agent emits an event.
38	type agentEventMsg struct {
39		agent string
40		ev    reviewtypes.Event
41	}
42	
43	// runFinishedMsg is sent when the orchestrator calls RunFinished.
44	type runFinishedMsg struct {
45		summary reviewtypes.RunSummary
46	}
47	
48	// tickMsg triggers spinner and duration column updates.
49	type tickMsg time.Time
50	
51	// reviewTUIModel is the Bubble Tea model for the review dashboard.
52	type reviewTUIModel struct {
53		rows         []agentRow
54		rowIdx       map[string]int // agent name → row index (O(1) lookup)
55		detailMode   bool
56		detailIdx    int // which agent is shown in drill-in
57		detailScroll int
58	
59		cancel     context.CancelFunc
60		cancelOnce *sync.Once
61	
62		spinner    spinner.Model
63		termWidth  int
64		termHeight int
65	
66		finished bool
67		summary  reviewtypes.RunSummary
68	}
69	
70	// newReviewTUIModel builds an initial model pre-populated with one row per
71	// agent. cancel is the shared CancelFunc; it must be the same one passed to
72	// NewTUISink.
73	func newReviewTUIModel(agents []string, cancel context.CancelFunc) reviewTUIModel {
74		sp := spinner.New()
75		sp.Spinner = spinner.Dot
76		sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
77	
78		rows := make([]agentRow, len(agents))
79		rowIdx := make(map[string]int, len(agents))
80		for i, name := range agents {
81			rows[i] = agentRow{
82				name:   name,
83				status: reviewtypes.AgentStatusUnknown,
84			}
85			rowIdx[name] = i
86		}
87		return reviewTUIModel{
88			rows:       rows,
89			rowIdx:     rowIdx,
90			cancel:     cancel,
91			cancelOnce: &sync.Once{},
92			spinner:    sp,
93			termWidth:  80,
94			termHeight: 24,
95		}
96	}
97	
98	// tickCmd schedules the next tick for duration/spinner refresh.
99	func tickCmd() tea.Cmd {
100		return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg {
101			return tickMsg(t)
102		})
103	}
104	
105	// Init returns the initial spinner tick command.
106	func (m reviewTUIModel) Init() tea.Cmd {
107		return tea.Batch(m.spinner.Tick, tickCmd())
108	}
109	
110	// Update handles all incoming messages.
111	func (m reviewTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
112		switch msg := msg.(type) {
113		case agentEventMsg:
114			return m.handleAgentEvent(msg)
115	
116		case runFinishedMsg:
117			m.finished = true
118			m.summary = msg.summary
119			// Sync each row's status from the orchestrator's summary. The
120			// in-stream events (Finished / RunError) update status as they
121			// arrive, but the orchestrator's classifyStatus has access to
122			// process-level signals (Wait error, ctx cancellation) that the
123			// event stream never surfaces. Without this sync, an agent that
124			// the orchestrator classified Cancelled (Ctrl+C path, no Finished
125			// emitted) or Failed (process exit non-zero, no Finished emitted)
126			// would still render as "running" in the final frame.
127			//
128			// Preserve any already-set status from the event stream — if the
129			// stream said Failed (RunError), the summary may say Succeeded
130			// (process exit 0); RunError stickiness wins. Only overwrite when
131			// the row is still in AgentStatusUnknown.
132			now := time.Now()
133			for i, run := range msg.summary.AgentRuns {
134				if i >= len(m.rows) {
135					break
136				}
137				if m.rows[i].status == reviewtypes.AgentStatusUnknown {
138					m.rows[i].status = run.Status
139				}
140				if m.rows[i].runEnd.IsZero() && !m.rows[i].runStart.IsZero() {
141					m.rows[i].runEnd = now
142				}
143			}
144			return m, nil
145	
146		case tickMsg:
147			var spinCmd tea.Cmd
148			m.spinner, spinCmd = m.spinner.Update(msg)
149			return m, tea.Batch(spinCmd, tickCmd())
150	
151		case spinner.TickMsg:
152			var spinCmd tea.Cmd
153			m.spinner, spinCmd = m.spinner.Update(msg)
154			return m, spinCmd
155	
156		case tea.WindowSizeMsg:
157			m.termWidth = msg.Width
158			m.termHeight = msg.Height
159			m = m.clampScroll()
160			return m, nil
161	
162		case tea.KeyPressMsg:
163			return m.handleKey(msg)
164		}
165		return m, nil
166	}
167	
168	// handleAgentEvent processes an agentEventMsg, updating the relevant row.
169	func (m reviewTUIModel) handleAgentEvent(msg agentEventMsg) (tea.Model, tea.Cmd) {
170		idx, ok := m.rowIdx[msg.agent]
171		if !ok {
172			return m, nil
173		}
174		row := &m.rows[idx]
175	
176		// Stamp run-start on the first event from this agent (per-row, not
177		// TUI-start; prevents inflated durations for late-starting agents).
178		if row.runStart.IsZero() {
179			row.runStart = time.Now()
180		}
181	
182		row.buffer = append(row.buffer, msg.ev)
183	
184		switch e := msg.ev.(type) {
185		case reviewtypes.Started:
186			// runStart already set; no other state update needed.
187		case reviewtypes.AssistantText:
188			collapsed := stringutil.CollapseWhitespace(sanitizeDisplayText(e.Text))
189			row.preview = truncateDisplayWidth(collapsed, 80)
190		case reviewtypes.Tokens:
191			row.tokens = e // cumulative: overwrite, not sum
192		case reviewtypes.Finished:
193			// RunError is sticky: if a prior RunError event already classified
194			// this row as Failed, a subsequent Finished{Success: true} must NOT
195			// flip it back to Succeeded. CU3's parser-fix-loop guarantees that
196			// RunError + Finished{Success:false} both accompany torn streams;
197			// matching that contract here keeps the TUI consistent with
198			// classifyStatus from CU4 (which honors sawRunError).
199			if row.status != reviewtypes.AgentStatusFailed {
200				if e.Success {
201					row.status = reviewtypes.AgentStatusSucceeded
202				} else {
203					row.status = reviewtypes.AgentStatusFailed
204				}
205			}
206			row.runEnd = time.Now()
207		case reviewtypes.RunError:
208			row.status = reviewtypes.AgentStatusFailed
209			row.err = e.Err
210			if row.runEnd.IsZero() {
211				row.runEnd = time.Now()
212			}
213		case reviewtypes.ToolCall:
214			// No visible state update for tool calls in the dashboard.
215		}
216	
217		// Auto-follow ONLY when the user is already at the bottom. This lets a
218		// user scroll up to inspect older events without each new event yanking
219		// them back to the tail. The pre-append max-scroll was for buffer
220		// length-1; if detailScroll was at-or-past that, the user was tailing.
221		if m.detailMode && m.detailIdx == idx {
222			preAppendMax := len(row.buffer) - 2 // -1 for the just-appended event, -1 for max-index
223			if preAppendMax < 0 || m.detailScroll >= preAppendMax {
224				m.detailScroll = m.maxDetailScroll()
225			}
226		}
227	
228		return m, nil
229	}
230	
231	// handleKey processes keyboard input.
232	func (m reviewTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
233		// Any key after finished dismisses.
234		if m.finished {
235			return m, tea.Quit
236		}
237	
238		switch {
239		case msg.Code == 'c' && msg.Mod == tea.ModCtrl:
240			if m.detailMode {
241				// In drill-in: Ctrl+C is intentionally ignored; Esc first.
242				return m, nil
243			}
244			m.cancelOnce.Do(m.cancel)
245			return m, tea.Quit
246	
247		case msg.Code == 'o' && msg.Mod == tea.ModCtrl:
248			if m.detailMode {
249				m.detailMode = false
250				return m, nil
251			}
252			m.detailMode = true
253			if len(m.rows) > 0 && (m.detailIdx < 0 || m.detailIdx >= len(m.rows)) {
254				m.detailIdx = 0
255			}
256			m.detailScroll = m.maxDetailScroll()
257			return m, nil
258	
259		case msg.Code == tea.KeyEscape || msg.Code == tea.KeyEsc:
260			if m.detailMode {
261				m.detailMode = false
262				return m, nil
263			}
264			return m, nil
265	
266		case msg.Code == tea.KeyLeft:
267			if m.detailMode && len(m.rows) > 0 {
268				m.detailIdx = (m.detailIdx - 1 + len(m.rows)) % len(m.rows)
269				m.detailScroll = m.maxDetailScroll()
270			}
271			return m, nil
272	
273		case msg.Code == tea.KeyRight:
274			if m.detailMode && len(m.rows) > 0 {
275				m.detailIdx = (m.detailIdx + 1) % len(m.rows)
276				m.detailScroll = m.maxDetailScroll()
277			}
278			return m, nil
279	
280		case msg.Code == tea.KeyUp:
281			if m.detailMode && m.detailScroll > 0 {
282				m.detailScroll--
283			}
284			return m, nil
285	
286		case msg.Code == tea.KeyDown:
287			if m.detailMode {
288				if maxScroll := m.maxDetailScroll(); m.detailScroll < maxScroll {
289					m.detailScroll++
290				}
291			}
292			return m, nil
293		}
294	
295		return m, nil
296	}
297	
298	// maxDetailScroll returns the largest valid detailScroll value for the current
299	// agent's buffer (0 when the buffer is empty or no rows exist).
300	func (m reviewTUIModel) maxDetailScroll() int {
301		if len(m.rows) == 0 {
302			return 0
303		}
304		n := len(m.rows[m.detailIdx].buffer)
305		if n == 0 {
306			return 0
307		}
308		return n - 1
309	}
310	
311	// clampScroll returns a copy of m with detailScroll clamped to valid bounds.
312	// Used after resize or index change.
313	func (m reviewTUIModel) clampScroll() reviewTUIModel {
314		maxScroll := m.maxDetailScroll()
315		if m.detailScroll > maxScroll {
316			m.detailScroll = maxScroll
317		}
318		return m
319	}
320	
321	// View renders the current state.
322	func (m reviewTUIModel) View() tea.View {
323		var content string
324		if m.detailMode && len(m.rows) > 0 {
325			content = detailView(m.rows[m.detailIdx], m.detailScroll, m.termWidth, m.termHeight)
326		} else {
327			content = m.dashboardView()
328		}
329		v := tea.NewView(content)
330		v.AltScreen = m.detailMode
331		return v
332	}
333	
334	// dashboardView renders the summary table.
335	func (m reviewTUIModel) dashboardView() string {
336		var b strings.Builder
337	
338		m.writeDashboardLine(&b, m.headerLine())
339	
340		for _, row := range m.rows {
341			m.writeDashboardLine(&b, m.renderRow(row))
342		}
343		b.WriteString("\n")
344	
345		if m.finished {
346			m.writeDashboardLine(&b, m.countsLine())
347			m.writeDashboardLine(&b, "Press any key to exit.")
348		} else {
349			m.writeDashboardLine(&b, "Ctrl+O: drill in · Ctrl+C: cancel")
350		}
351		return b.String()
352	}
353	
354	func (m reviewTUIModel) writeDashboardLine(b *strings.Builder, line string) {
355		b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
356		b.WriteString("\n")
357	}
358	
359	func (m reviewTUIModel) dashboardWidth() int {
360		if m.termWidth <= 0 {
361			return 80
362		}
363		return m.termWidth
364	}
365	
366	// headerLine returns the column header row.
367	func (m reviewTUIModel) headerLine() string {
368		return m.renderTableLine("AGENT", "STATUS", "DURATION", "TOKENS", "PREVIEW")
369	}
370	
371	// renderRow renders one agent row.
372	func (m reviewTUIModel) renderRow(row agentRow) string {
373		name := row.name
374	
375		var statusStr string
376		switch row.status {
377		case reviewtypes.AgentStatusSucceeded:
378			statusStr = "✓ done"
379		case reviewtypes.AgentStatusFailed:
380			statusStr = "✗ failed"
381		case reviewtypes.AgentStatusCancelled:
382			statusStr = "— cancel"
383		case reviewtypes.AgentStatusUnknown:
384			if row.runStart.IsZero() {
385				statusStr = "queued"
386			} else {
387				statusStr = m.spinner.View() + " running"
388			}
389		}
390	
391		durStr := ""
392		if !row.runStart.IsZero() {
393			if !row.runEnd.IsZero() {
394				durStr = formatDuration(row.runEnd.Sub(row.runStart))
395			} else {
396				durStr = formatDuration(time.Since(row.runStart))
397			}
398		}
399	
400		tokStr := ""
401		if row.tokens.In > 0 || row.tokens.Out > 0 {
402			tokStr = fmt.Sprintf("%s/%s", formatCompact(row.tokens.In), formatCompact(row.tokens.Out))
403		}
404	
405		return m.renderTableLine(name, statusStr, durStr, tokStr, row.preview)
406	}
407	
408	func (m reviewTUIModel) renderTableLine(agent, status, duration, tokens, preview string) string {
409		const (
410			agentWidth    = 20
411			statusWidth   = 10
412			durationWidth = 8
413			tokensWidth   = 8
414			minWidth      = agentWidth + statusWidth + durationWidth + tokensWidth + 8 // four two-space separators
415		)
416		termWidth := m.dashboardWidth()
417	
418		previewWidth := termWidth - minWidth
419		if previewWidth < 0 {
420			previewWidth = 0
421		}
422	
423		line := fmt.Sprintf("%s  %s  %s  %s  %s",
424			padDisplayWidth(agent, agentWidth),
425			padDisplayWidth(status, statusWidth),
426			padDisplayWidth(duration, durationWidth),
427			padDisplayWidth(tokens, tokensWidth),
428			truncateDisplayWidth(preview, previewWidth))
429		return truncateDisplayWidth(line, termWidth)
430	}
431	
432	// countsLine produces the summary line shown after the run finishes.
433	func (m reviewTUIModel) countsLine() string {
434		succ, fail, canc := 0, 0, 0
435		for _, r := range m.summary.AgentRuns {
436			switch r.Status {
437			case reviewtypes.AgentStatusSucceeded:
438				succ++
439			case reviewtypes.AgentStatusFailed:
440				fail++
441			case reviewtypes.AgentStatusCancelled:
442				canc++
443			case reviewtypes.AgentStatusUnknown:
444				// not counted
445			}
446		}
447		return fmt.Sprintf("%d agent(s) done — %d succeeded, %d failed, %d cancelled",
448			len(m.summary.AgentRuns), succ, fail, canc)
449	}
450	
451	// formatDuration formats a duration compactly for the table column.
452	func formatDuration(d time.Duration) string {
453		if d < time.Second {
454			return fmt.Sprintf("%dms", d.Milliseconds())
455		}
456		if d < time.Minute {
457			return fmt.Sprintf("%.1fs", d.Seconds())
458		}
459		return fmt.Sprintf("%dm%ds", int(d.Minutes()), int(d.Seconds())%60)
460	}
461	
462	// formatCompact formats a token count as e.g. "1.2k" or "450".
463	func formatCompact(n int) string {
464		if n >= 1000 {
465			return fmt.Sprintf("%.1fk", float64(n)/1000)
