// Package review — see env.go for package-level rationale.
//
// tui_model.go provides reviewTUIModel, the Bubble Tea Model for the
// review dashboard. The model renders a per-agent status table
// during the run and supports Ctrl+O drill-in mode for inspecting one agent's
// live event buffer on the alt screen.
package review

import (
	"context"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"time"

	"charm.land/bubbles/v2/spinner"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/stringutil"
)

// agentRow holds per-agent live state during the TUI run.
type agentRow struct {
	name     string
	status   reviewtypes.AgentStatus
	runStart time.Time          // stamped on first event from this agent
	runEnd   time.Time          // stamped on Finished/RunError event
	tokens   reviewtypes.Tokens // cumulative
	preview  string             // latest AssistantText preview, capped by display width
	buffer   []reviewtypes.Event
	err      error
}

// agentEventMsg is sent to the Bubble Tea program when an agent emits an event.
type agentEventMsg struct {
	agent string
	ev    reviewtypes.Event
}

// runFinishedMsg is sent when the orchestrator calls RunFinished.
type runFinishedMsg struct {
	summary reviewtypes.RunSummary
}

// tickMsg triggers spinner and duration column updates.
type tickMsg time.Time

// reviewTUIModel is the Bubble Tea model for the review dashboard.
type reviewTUIModel struct {
	rows         []agentRow
	rowIdx       map[string]int // agent name → row index (O(1) lookup)
	detailMode   bool
	detailIdx    int // which agent is shown in drill-in
	detailScroll int

	cancel     context.CancelFunc
	cancelOnce *sync.Once

	spinner    spinner.Model
	termWidth  int
	termHeight int

	finished bool
	summary  reviewtypes.RunSummary
}

// newReviewTUIModel builds an initial model pre-populated with one row per
// agent. cancel is the shared CancelFunc; it must be the same one passed to
// NewTUISink.
func newReviewTUIModel(agents []string, cancel context.CancelFunc) reviewTUIModel {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	rows := make([]agentRow, len(agents))
	rowIdx := make(map[string]int, len(agents))
	for i, name := range agents {
		rows[i] = agentRow{
			name:   name,
			status: reviewtypes.AgentStatusUnknown,
		}
		rowIdx[name] = i
	}
	return reviewTUIModel{
		rows:       rows,
		rowIdx:     rowIdx,
		cancel:     cancel,
		cancelOnce: &sync.Once{},
		spinner:    sp,
		termWidth:  80,
		termHeight: 24,
	}
}

// tickCmd schedules the next tick for duration/spinner refresh.
func tickCmd() tea.Cmd {
	return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

// Init returns the initial spinner tick command.
func (m reviewTUIModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, tickCmd())
}

// Update handles all incoming messages.
func (m reviewTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case agentEventMsg:
		return m.handleAgentEvent(msg)

	case runFinishedMsg:
		m.finished = true
		m.summary = msg.summary
		// Sync each row's status from the orchestrator's summary. The
		// in-stream events (Finished / RunError) update status as they
		// arrive, but the orchestrator's classifyStatus has access to
		// process-level signals (Wait error, ctx cancellation) that the
		// event stream never surfaces. Without this sync, an agent that
		// the orchestrator classified Cancelled (Ctrl+C path, no Finished
		// emitted) or Failed (process exit non-zero, no Finished emitted)
		// would still render as "running" in the final frame.
		//
		// Preserve any already-set status from the event stream — if the
		// stream said Failed (RunError), the summary may say Succeeded
		// (process exit 0); RunError stickiness wins. Only overwrite when
		// the row is still in AgentStatusUnknown.
		now := time.Now()
		for i, run := range msg.summary.AgentRuns {
			if i >= len(m.rows) {
				break
			}
			if m.rows[i].status == reviewtypes.AgentStatusUnknown {
				m.rows[i].status = run.Status
			}
			if m.rows[i].runEnd.IsZero() && !m.rows[i].runStart.IsZero() {
				m.rows[i].runEnd = now
			}
		}
		return m, nil

	case tickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, tea.Batch(spinCmd, tickCmd())

	case spinner.TickMsg:
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, spinCmd

	case tea.WindowSizeMsg:
		m.termWidth = msg.Width
		m.termHeight = msg.Height
		m = m.clampScroll()
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKey(msg)
	}
	return m, nil
}

// handleAgentEvent processes an agentEventMsg, updating the relevant row.
func (m reviewTUIModel) handleAgentEvent(msg agentEventMsg) (tea.Model, tea.Cmd) {
	idx, ok := m.rowIdx[msg.agent]
	if !ok {
		return m, nil
	}
	row := &m.rows[idx]

	// Stamp run-start on the first event from this agent (per-row, not
	// TUI-start; prevents inflated durations for late-starting agents).
	if row.runStart.IsZero() {
		row.runStart = time.Now()
	}

	row.buffer = append(row.buffer, msg.ev)

	switch e := msg.ev.(type) {
	case reviewtypes.Started:
		// runStart already set; no other state update needed.
	case reviewtypes.AssistantText:
		collapsed := stringutil.CollapseWhitespace(sanitizeDisplayText(e.Text))
		row.preview = truncateDisplayWidth(collapsed, 80)
	case reviewtypes.Tokens:
		row.tokens = e // cumulative: overwrite, not sum
	case reviewtypes.Finished:
		// RunError is sticky: if a prior RunError event already classified
		// this row as Failed, a subsequent Finished{Success: true} must NOT
		// flip it back to Succeeded. CU3's parser-fix-loop guarantees that
		// RunError + Finished{Success:false} both accompany torn streams;
		// matching that contract here keeps the TUI consistent with
		// classifyStatus from CU4 (which honors sawRunError).
		if row.status != reviewtypes.AgentStatusFailed {
			if e.Success {
				row.status = reviewtypes.AgentStatusSucceeded
			} else {
				row.status = reviewtypes.AgentStatusFailed
			}
		}
		row.runEnd = time.Now()
	case reviewtypes.RunError:
		row.status = reviewtypes.AgentStatusFailed
		row.err = e.Err
		if row.runEnd.IsZero() {
			row.runEnd = time.Now()
		}
	case reviewtypes.ToolCall:
		// No visible state update for tool calls in the dashboard.
	}

	// Auto-follow ONLY when the user is already at the bottom. This lets a
	// user scroll up to inspect older events without each new event yanking
	// them back to the tail. The pre-append max-scroll was for buffer
	// length-1; if detailScroll was at-or-past that, the user was tailing.
	if m.detailMode && m.detailIdx == idx {
		preAppendMax := len(row.buffer) - 2 // -1 for the just-appended event, -1 for max-index
		if preAppendMax < 0 || m.detailScroll >= preAppendMax {
			m.detailScroll = m.maxDetailScroll()
		}
	}

	return m, nil
}

// handleKey processes keyboard input.
func (m reviewTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	// Any key after finished dismisses.
	if m.finished {
		return m, tea.Quit
	}

	switch {
	case msg.Code == 'c' && msg.Mod == tea.ModCtrl:
		if m.detailMode {
			// In drill-in: Ctrl+C is intentionally ignored; Esc first.
			return m, nil
		}
		m.cancelOnce.Do(m.cancel)
		return m, tea.Quit

	case msg.Code == 'o' && msg.Mod == tea.ModCtrl:
		if m.detailMode {
			m.detailMode = false
			return m, nil
		}
		m.detailMode = true
		if len(m.rows) > 0 && (m.detailIdx < 0 || m.detailIdx >= len(m.rows)) {
			m.detailIdx = 0
		}
		m.detailScroll = m.maxDetailScroll()
		return m, nil

	case msg.Code == tea.KeyEscape || msg.Code == tea.KeyEsc:
		if m.detailMode {
			m.detailMode = false
			return m, nil
		}
		return m, nil

	case msg.Code == tea.KeyLeft:
		if m.detailMode && len(m.rows) > 0 {
			m.detailIdx = (m.detailIdx - 1 + len(m.rows)) % len(m.rows)
			m.detailScroll = m.maxDetailScroll()
		}
		return m, nil

	case msg.Code == tea.KeyRight:
		if m.detailMode && len(m.rows) > 0 {
			m.detailIdx = (m.detailIdx + 1) % len(m.rows)
			m.detailScroll = m.maxDetailScroll()
		}
		return m, nil

	case msg.Code == tea.KeyUp:
		if m.detailMode && m.detailScroll > 0 {
			m.detailScroll--
		}
		return m, nil

	case msg.Code == tea.KeyDown:
		if m.detailMode {
			if maxScroll := m.maxDetailScroll(); m.detailScroll < maxScroll {
				m.detailScroll++
			}
		}
		return m, nil
	}

	return m, nil
}

// maxDetailScroll returns the largest valid detailScroll value for the current
// agent's buffer (0 when the buffer is empty or no rows exist).
func (m reviewTUIModel) maxDetailScroll() int {
	if len(m.rows) == 0 {
		return 0
	}
	n := len(m.rows[m.detailIdx].buffer)
	if n == 0 {
		return 0
	}
	return n - 1
}

// clampScroll returns a copy of m with detailScroll clamped to valid bounds.
// Used after resize or index change.
func (m reviewTUIModel) clampScroll() reviewTUIModel {
	maxScroll := m.maxDetailScroll()
	if m.detailScroll > maxScroll {
		m.detailScroll = maxScroll
	}
	return m
}

// View renders the current state.
func (m reviewTUIModel) View() tea.View {
	var content string
	if m.detailMode && len(m.rows) > 0 {
		content = detailView(m.rows[m.detailIdx], m.detailScroll, m.termWidth, m.termHeight)
	} else {
		content = m.dashboardView()
	}
	v := tea.NewView(content)
	v.AltScreen = m.detailMode
	return v
}

// dashboardView renders the summary table.
func (m reviewTUIModel) dashboardView() string {
	var b strings.Builder

	m.writeDashboardLine(&b, m.headerLine())

	for _, row := range m.rows {
		m.writeDashboardLine(&b, m.renderRow(row))
	}
	b.WriteString("\n")

	if m.finished {
		m.writeDashboardLine(&b, m.countsLine())
		m.writeDashboardLine(&b, "Press any key to exit.")
	} else {
		m.writeDashboardLine(&b, "Ctrl+O: drill in · Ctrl+C: cancel")
	}
	return b.String()
}

func (m reviewTUIModel) writeDashboardLine(b *strings.Builder, line string) {
	b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
	b.WriteString("\n")
}

func (m reviewTUIModel) dashboardWidth() int {
	if m.termWidth <= 0 {
		return 80
	}
	return m.termWidth
}

// headerLine returns the column header row.
func (m reviewTUIModel) headerLine() string {
	return m.renderTableLine("AGENT", "STATUS", "DURATION", "TOKENS", "PREVIEW")
}

// renderRow renders one agent row.
func (m reviewTUIModel) renderRow(row agentRow) string {
	name := row.name

	var statusStr string
	switch row.status {
	case reviewtypes.AgentStatusSucceeded:
		statusStr = "✓ done"
	case reviewtypes.AgentStatusFailed:
		statusStr = "✗ failed"
	case reviewtypes.AgentStatusCancelled:
		statusStr = "— cancel"
	case reviewtypes.AgentStatusUnknown:
		if row.runStart.IsZero() {
			statusStr = "queued"
		} else {
			statusStr = m.spinner.View() + " running"
		}
	}

	durStr := ""
	if !row.runStart.IsZero() {
		if !row.runEnd.IsZero() {
			durStr = formatDuration(row.runEnd.Sub(row.runStart))
		} else {
			durStr = formatDuration(time.Since(row.runStart))
		}
	}

	tokStr := ""
	if row.tokens.In > 0 || row.tokens.Out > 0 {
		tokStr = fmt.Sprintf("%s/%s", formatCompact(row.tokens.In), formatCompact(row.tokens.Out))
	}

	return m.renderTableLine(name, statusStr, durStr, tokStr, row.preview)
}

func (m reviewTUIModel) renderTableLine(agent, status, duration, tokens, preview string) string {
	const (
		agentWidth    = 20
		statusWidth   = 10
		durationWidth = 8
		tokensWidth   = 8
		minWidth      = agentWidth + statusWidth + durationWidth + tokensWidth + 8 // four two-space separators
	)
	termWidth := m.dashboardWidth()

	previewWidth := termWidth - minWidth
	if previewWidth < 0 {
		previewWidth = 0
	}

	line := fmt.Sprintf("%s  %s  %s  %s  %s",
		padDisplayWidth(agent, agentWidth),
		padDisplayWidth(status, statusWidth),
		padDisplayWidth(duration, durationWidth),
		padDisplayWidth(tokens, tokensWidth),
		truncateDisplayWidth(preview, previewWidth))
	return truncateDisplayWidth(line, termWidth)
}

// countsLine produces the summary line shown after the run finishes.
func (m reviewTUIModel) countsLine() string {
	succ, fail, canc := 0, 0, 0
	for _, r := range m.summary.AgentRuns {
		switch r.Status {
		case reviewtypes.AgentStatusSucceeded:
			succ++
		case reviewtypes.AgentStatusFailed:
			fail++
		case reviewtypes.AgentStatusCancelled:
			canc++
		case reviewtypes.AgentStatusUnknown:
			// not counted
		}
	}
	return fmt.Sprintf("%d agent(s) done — %d succeeded, %d failed, %d cancelled",
		len(m.summary.AgentRuns), succ, fail, canc)
}

// formatDuration formats a duration compactly for the table column.
func formatDuration(d time.Duration) string {
	if d < time.Second {
		return fmt.Sprintf("%dms", d.Milliseconds())
	}
	if d < time.Minute {
		return fmt.Sprintf("%.1fs", d.Seconds())
	}
	return fmt.Sprintf("%dm%ds", int(d.Minutes()), int(d.Seconds())%60)
}

// formatCompact formats a token count as e.g. "1.2k" or "450".
func formatCompact(n int) string {
	if n >= 1000 {
		return fmt.Sprintf("%.1fk", float64(n)/1000)
	}
	return strconv.Itoa(n)
}

// Package review — see env.go for package-level rationale.
//
// tui_sink.go provides TUISink, a Sink implementation that renders a Bubble
// Tea status dashboard during a review run and supports Ctrl+O
// drill-in mode for inspecting one agent's live event buffer. Used in
// interactive (TTY) runs; non-TTY runs use DumpSink instead.
package review

import (
	"context"
	"io"
	"sync"

	tea "charm.land/bubbletea/v2"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// TUISink is a Sink that renders a Bubble Tea dashboard. The orchestrator
// calls AgentEvent/RunFinished from a single goroutine (CU4 serial-dispatch
// contract); the sink translates each event into a tea.Msg and sends it via
// Program.Send. Bubble Tea's Send is thread-safe, but we never rely on that
// property — the serial-dispatch promise means Send is only called from the
// orchestrator's dispatch goroutine.
//
// Cancellation: cancel is the same context.CancelFunc that controls the
// orchestrator's run context. KeyCtrlC in the dashboard calls this function
// (gated by a sync.Once in the model). Out-of-TUI SIGINT routes through the
// cobra root's context, which cancels the same function — no parallel
// signal.Notify goroutine is needed here.
type TUISink struct {
	program *tea.Program

	mu       sync.Mutex
	started  bool
	finished bool

	done chan struct{} // closed when the tea.Program exits
}

// Compile-time interface check.
var _ reviewtypes.Sink = (*TUISink)(nil)

// NewTUISink creates a TUISink wired to cancel for Ctrl+C handling. agents is
// the ordered list of agent names that will run; the dashboard pre-renders one
// row per agent so the user sees the full run shape from the first frame.
// output is the writer the Bubble Tea program renders into (typically
// cmd.OutOrStdout()).
//
// tea.WithoutSignalHandler keeps SIGINT routing on the cobra root's existing
// handler (which cancels the run context), so the TUI's KeyCtrlC path and the
// OS signal path share a single cancel function with no race.
func NewTUISink(agents []string, cancel context.CancelFunc, output io.Writer) *TUISink {
	model := newReviewTUIModel(agents, cancel)
	prog := tea.NewProgram(
		model,
		tea.WithOutput(output),
		tea.WithoutSignalHandler(), // SIGINT handled by cobra root; KeyCtrlC calls cancel directly
	)
	return &TUISink{
		program: prog,
		done:    make(chan struct{}),
	}
}

// Start spawns the Bubble Tea program in its own goroutine. Must be called
// before any AgentEvent calls. Subsequent calls are no-ops.
func (s *TUISink) Start() {
	s.mu.Lock()
	if s.started {
		s.mu.Unlock()
		return
	}
	s.started = true
	s.mu.Unlock()

	go func() {
		defer close(s.done)
		if _, err := s.program.Run(); err != nil {
			// Bubble Tea program errors are non-actionable in a background
			// goroutine (e.g., terminal resize race on exit). Log nothing —
			// the run result is available via RunSummary and the sink's
			// finished state. Swallowing is intentional.
			_ = err
		}
	}()
}

// Wait blocks until the Bubble Tea program exits. Safe to call after Start.
// If Start was never called, Wait returns immediately.
func (s *TUISink) Wait() {
	s.mu.Lock()
	started := s.started
	s.mu.Unlock()
	if !started {
		return
	}
	<-s.done
}

// AgentEvent (Sink interface): translate ev into a tea.Msg and Send it to the
// Bubble Tea program. Implements the serial-dispatch contract: the orchestrator
// calls this from a single goroutine.
//
// Note: Send is safe to call from goroutines other than the TUI's update loop;
// Bubble Tea's implementation queues the message internally.
func (s *TUISink) AgentEvent(agent string, ev reviewtypes.Event) {
	s.mu.Lock()
	ok := s.started && !s.finished
	s.mu.Unlock()
	if !ok {
		return
	}
	s.program.Send(agentEventMsg{agent: agent, ev: ev})
}

// RunFinished (Sink interface): mark the run complete and send the final
// summary message. The TUI shows the dashboard one more frame with the
// terminal statuses and waits for the user to press any key to dismiss.
//
// IMPORTANT: RunFinished blocks until the user dismisses (presses any key)
// so that post-run sinks (e.g. DumpSink) render their narrative AFTER the
// TUI has exited and the terminal is back in normal mode.
func (s *TUISink) RunFinished(summary reviewtypes.RunSummary) {
	s.mu.Lock()
	if s.finished {
		s.mu.Unlock()
		return
	}
	s.finished = true
	s.mu.Unlock()

	s.program.Send(runFinishedMsg{summary: summary})
	// Block until the Bubble Tea program exits (user presses any key after
	// seeing the final dashboard, or Ctrl+C was already received and the
	// program already quit).
	s.Wait()
}

// Package investigate — see env.go for package-level rationale.
//
// cmd.go provides NewCommand(), the cobra entry point for `entire
// investigate`. The command bootstraps shared findings/timeline docs and
// drives a round-robin multi-agent investigation loop via
// RunInvestigateLoop. The cobra wiring mirrors `entire review` (cmd.go in
// the review package): a Deps struct collects runtime-injectable hooks so
// tests can stub spawners, picker forms, and the loop runner without
// needing real TTY or agent binaries.
package investigate

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/agent/spawn"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// Deps collects the runtime-injectable hooks NewCommand needs from the
// parent cli package. Tests stub fields to drive branches that would
// otherwise require a real TTY or enabled repo.
type Deps struct {
	// GetAgentsWithHooksInstalled returns the registry names of all agents
	// whose lifecycle hooks are installed in the current repo.
	GetAgentsWithHooksInstalled func(ctx context.Context) []types.AgentName

	// NewSilentError wraps an error so the cobra root does not double-print
	// it.
	NewSilentError func(err error) error

	// SpawnerFor maps an agent name → Spawner (claude-code, codex,
	// gemini-cli). Returns nil for non-launchable agents. Wired by
	// investigate_bridge.go in a later task.
	SpawnerFor func(agentName string) spawn.Spawner

	// LaunchFix delegates to agentlaunch.LaunchFixAgent in production. Tests
	// inject a stub.
	LaunchFix func(ctx context.Context, agentName string, prompt string) error

	// PriorEntireContextFn returns the "## Prior Entire Context" body for
	// the seed-doc scaffold. Production may run `entire search` or read
	// checkpoints; tests pass nil to skip the block.
	PriorEntireContextFn func(ctx context.Context, topic string) string

	// AttachCmd is the optional `entire investigate attach <session-id>`
	// subcommand. Wired in a later task.
	AttachCmd *cobra.Command

	// LoopRun, when non-nil, replaces RunInvestigateLoop. Tests inject a
	// stub to capture LoopInput and return a canned LoopResult.
	LoopRun func(ctx context.Context, in LoopInput, ldeps LoopDeps) (LoopResult, error)
}

// runFlags collects the flag values the run path inspects. Captured into a
// struct so helpers don't need a giant signature.
type runFlags struct {
	topic     string
	issueLink string
	agentsCSV string
	maxTurns  int
	quorum    int
	output    string
	cont      string
	edit      bool
	findings  bool
	verbose   bool
}

// NewCommand returns the `entire investigate` cobra command wired with the
// provided deps. Callers in the cli package pass a fully-populated Deps;
// tests pass a Deps with stub fields.
func NewCommand(deps Deps) *cobra.Command {
	flags := runFlags{}

	cmd := &cobra.Command{
		Use:   "investigate [seed-doc]",
		Short: "Run a multi-agent investigation against the current branch",
		// Hidden from `entire help` while the feature is still maturing —
		// users who know about it can still run it normally.
		Hidden: true,
		Long: `Run a multi-agent investigation. Agents take turns appending findings,
evidence, and analysis to a shared findings document until quorum is reached.

Labs entry: investigate is experimental. We are actively refining it based on
user feedback.

Inputs (mutually exclusive):
  [seed-doc]              positional path to a starting findings file
  --topic "<question>"    free-form topic to investigate
  --issue-link <url>      GitHub issue or PR URL (resolved via gh)

Flags:
  --agents <csv>          override configured agents (comma-separated)
  --max-turns N           per-agent turn budget (default 3)
  --quorum N              approvals needed to terminate (0 = all agents)
  --output <path>         override findings doc path
  --continue <run-id>     resume an existing run
  --edit                  re-open the investigate config picker
  --findings              browse local investigation manifests
  --verbose               tee per-turn agent stdout to the terminal

Subcommands:
  fix [run-id]            launch a coding agent with the run's findings as
                          grounded context`,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most one seed-doc path, received %d", len(args))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			if err := validateFlags(args, flags); err != nil {
				return err
			}
			return runInvestigate(ctx, cmd, args, flags, deps)
		},
	}

	cmd.Flags().StringVar(&flags.topic, "topic", "", "free-form topic to investigate")
	cmd.Flags().StringVar(&flags.issueLink, "issue-link", "", "GitHub issue or PR URL")
	cmd.Flags().StringVar(&flags.agentsCSV, "agents", "", "override configured agents (comma-separated)")
	cmd.Flags().IntVar(&flags.maxTurns, "max-turns", 0, "per-agent turn budget (default 3)")
	cmd.Flags().IntVar(&flags.quorum, "quorum", 0, "approvals needed to terminate (0 = all agents)")
	cmd.Flags().StringVar(&flags.output, "output", "", "override findings doc path")
	cmd.Flags().StringVar(&flags.cont, "continue", "", "resume an existing run by id")
	cmd.Flags().BoolVar(&flags.edit, "edit", false, "re-open the investigate config picker")
	cmd.Flags().BoolVar(&flags.findings, "findings", false, "browse local investigation manifests")
	cmd.Flags().BoolVar(&flags.verbose, "verbose", false, "tee per-turn agent stdout to the terminal")

	cmd.AddCommand(newFixSubcommand(deps))
	if deps.AttachCmd != nil {
		cmd.AddCommand(deps.AttachCmd)
	}
	return cmd
}

// validateFlags enforces the mutual-exclusion rules described in the long
// help text. Run before any I/O so usage errors are visible without
// touching disk.
func validateFlags(args []string, f runFlags) error {
	seedSet := len(args) == 1
	topicSet := strings.TrimSpace(f.topic) != ""
	issueSet := strings.TrimSpace(f.issueLink) != ""
	contSet := strings.TrimSpace(f.cont) != ""

	inputCount := 0
	for _, set := range []bool{seedSet, topicSet, issueSet} {
		if set {
			inputCount++
		}
	}
	if inputCount > 1 {
		return errors.New("at most one of [seed-doc], --topic, --issue-link may be set")
	}

	if contSet && inputCount > 0 {
		return errors.New("--continue is mutually exclusive with [seed-doc]/--topic/--issue-link")
	}

	modes := 0
	for _, m := range []bool{f.edit, f.findings} {
		if m {
			modes++
		}
	}
	if modes > 1 {
		return errors.New("--edit and --findings are mutually exclusive")
	}
	if (f.edit || f.findings) && (inputCount > 0 || contSet) {
		return errors.New("--edit and --findings cannot be combined with a run input")
	}

	return nil
}

// newFixSubcommand wires `entire investigate fix [run-id]` to RunFix.
func newFixSubcommand(deps Deps) *cobra.Command {
	return &cobra.Command{
		Use:   "fix [run-id]",
		Short: "Launch a coding agent with a saved investigation as grounded context",
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most one run id, received %d", len(args))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			if _, err := paths.WorktreeRoot(ctx); err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
				return wrapSilent(deps.NewSilentError, errors.New("not a git repository"))
			}
			store, err := NewLocalManifestStore(ctx)
			if err != nil {
				return fmt.Errorf("open manifest store: %w", err)
			}
			runID := ""
			if len(args) == 1 {
				runID = args[0]
			}
			launch := deps.LaunchFix
			if launch == nil {
				return errors.New("fix: launch function not wired")
			}
			return RunFix(ctx, FixInput{
				RunID:  runID,
				Out:    cmd.OutOrStdout(),
				ErrOut: cmd.ErrOrStderr(),
			}, FixDeps{
				ManifestStore: store,
				Launch:        launch,
			})
		},
	}
}

// runInvestigate is the main run path. It pre-flights the repo, dispatches
// to --edit/--findings/--continue branches, then invokes the loop.
func runInvestigate(ctx context.Context, cmd *cobra.Command, args []string, f runFlags, deps Deps) error {
	silentErr := deps.NewSilentError

	if _, err := paths.WorktreeRoot(ctx); err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
		return wrapSilent(silentErr, errors.New("not a git repository"))
	}

	if f.edit {
		return runEdit(ctx, cmd, deps)
	}
	if f.findings {
		return runInvestigateFindings(ctx, cmd, silentErr)
	}
	if strings.TrimSpace(f.cont) != "" {
		return runContinue(ctx, cmd, f, deps)
	}
	return runFresh(ctx, cmd, args, f, deps)
}

// runEdit re-opens the config picker and persists the result.
func runEdit(ctx context.Context, cmd *cobra.Command, deps Deps) error {
	out := cmd.OutOrStdout()
	cfg, err := RunInvestigateConfigPicker(ctx, out, deps.SpawnerFor, deps.GetAgentsWithHooksInstalled)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(deps.NewSilentError, err)
	}
	if cfg == nil {
		return nil
	}
	return saveInvestigateConfig(ctx, cfg)
}

// saveInvestigateConfig persists cfg into .entire/settings.json while
// preserving every other settings field. Mirrors review.SaveReviewConfig.
func saveInvestigateConfig(ctx context.Context, cfg *settings.InvestigateConfig) error {
	s, err := settings.Load(ctx)
	if err != nil {
		return fmt.Errorf("load settings before save: %w", err)
	}
	if s == nil {
		s = &settings.EntireSettings{}
	}
	s.Investigate = cfg
	if err := settings.Save(ctx, s); err != nil {
		return fmt.Errorf("save settings: %w", err)
	}
	return nil
}

// runContinue resumes an existing run from persisted RunState.
func runContinue(ctx context.Context, cmd *cobra.Command, f runFlags, deps Deps) error {
	silentErr := deps.NewSilentError

	store, err := NewStateStore(ctx)
	if err != nil {
		return fmt.Errorf("open run state store: %w", err)
	}
	state, err := store.Load(ctx, f.cont)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}
	if state == nil {
		err := fmt.Errorf("no run state found for run id %q", f.cont)
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}

	agents := state.Agents
	if csv := strings.TrimSpace(f.agentsCSV); csv != "" {
		agents = parseAgentsCSV(csv)
	}
	if err := verifyAgentsLaunchable(ctx, agents, deps); err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}
	// state.NextAgentIdx is the index into agents the next turn will use.
	// If --agents shrinks the list (or the persisted state is otherwise
	// inconsistent), the loop would index out of range on the first turn.
	// Refuse rather than crash: the user gets an actionable error and the
	// state file is left intact for them to either fix the override or
	// `entire investigate --findings` and start fresh.
	if state.NextAgentIdx >= len(agents) {
		err := fmt.Errorf(
			"cannot resume: persisted next agent index %d exceeds available agents (%d). "+
				"This usually means --agents was used with a shorter list than the original run. "+
				"Either re-run with the original agents (or a superset), or remove the run state at "+
				".git/entire-investigations/state/%s.json and start a fresh investigation",
			state.NextAgentIdx, len(agents), state.RunID)
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}

	maxTurns := state.MaxTurns
	if f.maxTurns > 0 {
		maxTurns = f.maxTurns
	}
	quorum := state.Quorum
	if f.quorum > 0 {
		quorum = f.quorum
	}

	// AlwaysPrompt is not persisted in RunState — it's a settings-level
	// customization that the user controls outside the run. Load it fresh
	// on resume so a configured "be skeptical" preamble survives Ctrl+C.
	// If settings.Load fails (e.g. the file was hand-edited and is now
	// malformed), surface a warning so the user notices their preamble has
	// silently disappeared instead of letting the agent's behaviour change
	// mid-investigation with no explanation.
	alwaysPrompt := ""
	if s, sErr := settings.Load(ctx); sErr != nil {
		fmt.Fprintf(cmd.ErrOrStderr(),
			"Warning: could not reload settings on --continue (%v). The configured "+
				"investigate.always_prompt is not being applied to this resumed run.\n", sErr)
	} else if s != nil && s.Investigate != nil {
		alwaysPrompt = s.Investigate.AlwaysPrompt
	}

	in := LoopInput{
		RunID:        state.RunID,
		Topic:        state.Topic,
		Agents:       agents,
		MaxTurns:     maxTurns,
		Quorum:       quorum,
		AlwaysPrompt: alwaysPrompt,
		FindingsDoc:  state.FindingsDoc,
		TimelineDoc:  state.TimelineDoc,
		StartingSHA:  state.StartingSHA,
		Resume:       state,
	}
	fmt.Fprintf(cmd.OutOrStdout(), "Resuming investigation: %q (run %s)\n", state.Topic, state.RunID)
	return executeLoop(ctx, cmd, in, deps)
}

// runFresh handles the full first-run path: bootstrap docs, build initial
// state, dispatch to the loop, persist a manifest.
func runFresh(ctx context.Context, cmd *cobra.Command, args []string, f runFlags, deps Deps) error {
	silentErr := deps.NewSilentError

	s, err := settings.Load(ctx)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintf(cmd.ErrOrStderr(), "Failed to load settings: %v\n", err)
		fmt.Fprintln(cmd.ErrOrStderr(), "Fix `.entire/settings.json` and re-run `entire investigate`.")
		return wrapSilent(silentErr, err)
	}
	if s == nil || s.Investigate.IsZero() {
		if !ConfirmFirstRunSetup(ctx, cmd.OutOrStdout()) {
			return nil
		}
		cfg, pickErr := RunInvestigateConfigPicker(ctx, cmd.OutOrStdout(), deps.SpawnerFor, deps.GetAgentsWithHooksInstalled)
		if pickErr != nil {
			cmd.SilenceUsage = true
			fmt.Fprintln(cmd.ErrOrStderr(), pickErr.Error())
			return wrapSilent(silentErr, pickErr)
		}
		if cfg == nil {
			return nil
		}
		if saveErr := saveInvestigateConfig(ctx, cfg); saveErr != nil {
			return saveErr
		}
		if s == nil {
			s = &settings.EntireSettings{}
		}
		s.Investigate = cfg
		fmt.Fprintln(cmd.OutOrStdout())
		fmt.Fprintln(cmd.OutOrStdout(), "Setup complete — running investigation now.")
	}

	agents, maxTurns, quorum, err := resolveRunConfig(s.Investigate, f)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}
	if err := verifyAgentsLaunchable(ctx, agents, deps); err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve worktree root: %w", err)
	}
	headSHA, err := currentHeadSHA(ctx, worktreeRoot)
	if err != nil {
		return fmt.Errorf("resolve HEAD: %w", err)
	}

	runID, err := newRunID()
	if err != nil {
		return fmt.Errorf("generate run id: %w", err)
	}

	topic, seedDoc, issueSeed, issueTopic, err := resolveTopicAndSeed(ctx, args, f)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
		return wrapSilent(silentErr, err)
	}

	findingsDoc, timelineDoc := resolveDocPaths(worktreeRoot, topic, f.output)

	priorContext := ""
	if deps.PriorEntireContextFn != nil {
		priorContext = deps.PriorEntireContextFn(ctx, topic)
	}

	bres, err := Bootstrap(ctx, BootstrapInput{
		SeedDoc:            seedDoc,
		Topic:              topicForBootstrap(topic, seedDoc, issueSeed),
		IssueLinkSeed:      issueSeed,
		IssueLinkTopic:     issueTopic,
		FindingsDoc:        findingsDoc,
		TimelineDoc:        timelineDoc,
		PriorEntireContext: priorContext,
	})
	if err != nil {
		return fmt.Errorf("bootstrap docs: %w", err)
	}
	if strings.TrimSpace(bres.Topic) != "" {
		topic = bres.Topic
	}

	fmt.Fprintf(cmd.OutOrStdout(), "Investigating: %q (run %s)\n", topic, runID)
	fmt.Fprintf(cmd.OutOrStdout(), "  Findings: %s\n", findingsDoc)
	fmt.Fprintf(cmd.OutOrStdout(), "  Timeline: %s\n", timelineDoc)

	startedAt := time.Now().UTC()
	in := LoopInput{
		RunID:        runID,
		Topic:        topic,
		Agents:       agents,
		MaxTurns:     maxTurns,
		Quorum:       quorum,
		AlwaysPrompt: s.Investigate.AlwaysPrompt,
		FindingsDoc:  findingsDoc,
		TimelineDoc:  timelineDoc,
		StartingSHA:  headSHA,
		PriorContext: priorContext,
	}
	result, err := executeLoopAndCapture(ctx, cmd, in, deps)
	if err != nil {
		return err
	}

	endedAt := time.Now().UTC()
	writeRunManifest(ctx, cmd.OutOrStdout(), runID, topic, agents, headSHA, worktreeRoot,
		findingsDoc, timelineDoc, startedAt, endedAt, result)
	return nil
}

// resolveRunConfig derives the effective agents / max-turns / quorum from
// settings, with --agents / --max-turns / --quorum overrides taking
// precedence.
func resolveRunConfig(cfg *settings.InvestigateConfig, f runFlags) (agents []string, maxTurns int, quorum int, err error) {
	if cfg == nil {
		return nil, 0, 0, errors.New("no investigate config; run `entire investigate --edit` first")
	}
	agents = append([]string(nil), cfg.Agents...)
	if csv := strings.TrimSpace(f.agentsCSV); csv != "" {
		agents = parseAgentsCSV(csv)
	}
	if len(agents) == 0 {
		return nil, 0, 0, errors.New("no agents configured for investigate; run `entire investigate --edit`")
	}
	maxTurns = cfg.MaxTurns
	if f.maxTurns > 0 {
		maxTurns = f.maxTurns
	}
	quorum = cfg.Quorum
	if f.quorum > 0 {
		quorum = f.quorum
	}
	return agents, maxTurns, quorum, nil
}

// parseAgentsCSV splits a comma-separated agent list, trimming whitespace
// and dropping empty entries.
func parseAgentsCSV(csv string) []string {
	parts := strings.Split(csv, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if v := strings.TrimSpace(p); v != "" {
			out = append(out, v)
		}
	}
	return out
}

// verifyAgentsLaunchable confirms each agent has a non-nil Spawner AND has
// hooks installed in the current repo.
func verifyAgentsLaunchable(ctx context.Context, agents []string, deps Deps) error {
	if deps.SpawnerFor == nil {
		return errors.New("investigate: SpawnerFor not wired")
	}
	if deps.GetAgentsWithHooksInstalled == nil {
		return errors.New("investigate: GetAgentsWithHooksInstalled not wired")
	}
	installed := deps.GetAgentsWithHooksInstalled(ctx)
	installedSet := make(map[string]struct{}, len(installed))
	for _, n := range installed {
		installedSet[string(n)] = struct{}{}
	}
	for _, name := range agents {
		if deps.SpawnerFor(name) == nil {
			return fmt.Errorf("agent %q is not launchable (spawner missing)", name)
		}
		if _, ok := installedSet[name]; !ok {
			return fmt.Errorf("agent %q is not launchable (run `entire configure --agent %s` first)", name, name)
		}
	}
	return nil
}

// resolveTopicAndSeed turns the user's input args into a topic + (seed
// doc path | issue link seed bytes + topic). Exactly one of seedDoc /
// issueSeed / topic-only is set on return.
func resolveTopicAndSeed(ctx context.Context, args []string, f runFlags) (topic, seedDoc string, issueSeed []byte, issueTopic string, err error) {
	switch {
	case len(args) == 1:
		seedDoc = args[0]
		body, readErr := os.ReadFile(seedDoc) //nolint:gosec // path is user-supplied positional arg
		if readErr != nil {
			return "", "", nil, "", fmt.Errorf("read seed doc %s: %w", seedDoc, readErr)
		}
		topic = DeriveTopicFromSeed(body, seedDoc)
		return topic, seedDoc, nil, "", nil
	case strings.TrimSpace(f.topic) != "":
		topic = strings.TrimSpace(f.topic)
		return topic, "", nil, "", nil
	case strings.TrimSpace(f.issueLink) != "":
		res, resErr := ResolveIssueLink(ctx, f.issueLink)
		if resErr != nil {
			return "", "", nil, "", resErr
		}
		return res.Topic, "", res.SeedDoc, res.Topic, nil
	default:
		return "", "", nil, "", errors.New("missing investigation input: pass [seed-doc], --topic, or --issue-link")
	}
}

// topicForBootstrap returns the topic value to embed in the bootstrap
// scaffold. The seed-doc path takes precedence (Bootstrap re-derives from
// the seed body), and the issue-link path uses IssueLinkTopic; only the
// topic-only path puts the resolved topic into BootstrapInput.Topic.
func topicForBootstrap(topic, seedDoc string, issueSeed []byte) string {
	if seedDoc != "" || len(issueSeed) > 0 {
		return ""
	}
	return topic
}

// resolveDocPaths returns the absolute findings + timeline paths. When
// override is set, the findings doc is placed there (with -timeline.md
// appended for the timeline). Otherwise both go under
// .entire/investigations/.
func resolveDocPaths(worktreeRoot, topic, override string) (findings, timeline string) {
	slug := SlugifyTopic(topic)
	if strings.TrimSpace(override) != "" {
		findings = override
		if !filepath.IsAbs(findings) {
			findings = filepath.Join(worktreeRoot, findings)
		}
	} else {
		findings = filepath.Join(worktreeRoot, ".entire", "investigations", slug+".md")
	}
	timeline = strings.TrimSuffix(findings, filepath.Ext(findings)) + "-timeline.md"
	return findings, timeline
}

// executeLoop runs the investigation loop without writing a manifest.
// Used by the --continue path, where the manifest already exists.
func executeLoop(ctx context.Context, cmd *cobra.Command, in LoopInput, deps Deps) error {
	_, err := executeLoopAndCapture(ctx, cmd, in, deps)
	return err
}

// executeLoopAndCapture runs the loop and returns the LoopResult so the
// caller can use it to compose a post-run manifest / footer.
func executeLoopAndCapture(ctx context.Context, cmd *cobra.Command, in LoopInput, deps Deps) (LoopResult, error) {
	stateStore, err := NewStateStore(ctx)
	if err != nil {
		return LoopResult{}, fmt.Errorf("open run state store: %w", err)
	}
	commonDir, err := gitCommonDirForTranscripts(ctx)
	if err != nil {
		return LoopResult{}, err
	}
	transcriptDir := filepath.Join(commonDir, InvestigationsDirName, "transcripts")

	verboseOut := io.Writer(nil)
	if cmd.Flags().Changed("verbose") {
		v, getErr := cmd.Flags().GetBool("verbose")
		if getErr != nil {
			return LoopResult{}, fmt.Errorf("read --verbose flag: %w", getErr)
		}
		if v {
			verboseOut = cmd.OutOrStdout()
		}
	}

	ldeps := LoopDeps{
		SpawnerFor:    deps.SpawnerFor,
		States:        stateStore,
		TranscriptDir: transcriptDir,
		VerboseOut:    verboseOut,
		ProgressOut:   cmd.OutOrStdout(),
	}

	runner := deps.LoopRun
	if runner == nil {
		runner = RunInvestigateLoop
	}
	result, runErr := runner(ctx, in, ldeps)
	if runErr != nil {
		return result, fmt.Errorf("investigate loop: %w", runErr)
	}
	return result, nil
}

// gitCommonDirForTranscripts resolves the git common dir via the same
// helper StateStore uses, so per-turn transcripts live alongside the run
// state.
func gitCommonDirForTranscripts(ctx context.Context) (string, error) {
	store, err := NewStateStore(ctx)
	if err != nil {
		return "", err
	}
	// store.dir is <commonDir>/entire-investigations/state — strip the two
	// trailing components to recover commonDir.
	dir := store.dir
	dir = filepath.Dir(dir) // entire-investigations
	dir = filepath.Dir(dir) // commonDir
	return dir, nil
}

// writeRunManifest builds a LocalManifest from the loop result and
// persists it. Failures are logged but do not error — the docs themselves
// are the deliverable.
func writeRunManifest(
	ctx context.Context,
	out io.Writer,
	runID, topic string,
	agents []string,
	startingSHA, worktreePath, findingsDoc, timelineDoc string,
	startedAt, endedAt time.Time,
	result LoopResult,
) {
	manifestStore, err := NewLocalManifestStore(ctx)
	if err != nil {
		logging.Debug(ctx, "investigate: open manifest store",
			slog.String("err", err.Error()), slog.String("run_id", runID))
		return
	}
	stancesByAgent := map[string]string{}
	if result.State != nil {
		for _, s := range result.State.Stances {
			stancesByAgent[s.Agent] = s.Stance
		}
	}
	if startedAt.IsZero() && result.State != nil {
		startedAt = result.State.StartedAt
	}
	if endedAt.IsZero() {
		endedAt = time.Now().UTC()
	}
	m := LocalManifest{
		RunID:          runID,
		Topic:          topic,
		Slug:           SlugifyTopic(topic),
		StartingSHA:    startingSHA,
		WorktreePath:   worktreePath,
		FindingsDoc:    findingsDoc,
		TimelineDoc:    timelineDoc,
		Agents:         append([]string(nil), agents...),
		Outcome:        string(result.Outcome),
		StancesByAgent: stancesByAgent,
		StartedAt:      startedAt,
		EndedAt:        endedAt,
	}
	if writeErr := manifestStore.Write(ctx, m); writeErr != nil {
		logging.Debug(ctx, "investigate: manifest write failed",
			slog.String("err", writeErr.Error()), slog.String("run_id", runID))
		return
	}
	writeInvestigateFooter(out, m)
}

// writeInvestigateFooter prints the post-run summary + how to run
// `entire investigate fix`.
func writeInvestigateFooter(w io.Writer, m LocalManifest) {
	fmt.Fprintln(w)
	if m.Outcome != "" {
		fmt.Fprintf(w, "Outcome: %s\n", m.Outcome)
	}
	fmt.Fprintln(w, "Investigation complete.")
	fmt.Fprintln(w, "Findings: "+m.FindingsDoc)
	fmt.Fprintln(w, "Timeline: "+m.TimelineDoc)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "To apply these findings:")
	fmt.Fprintf(w, "  entire investigate fix %s\n", m.RunID)
}

// newRunID returns a fresh 12-hex-char run identifier. Mirrors the
// checkpoint-id format used by the strategy package.
func newRunID() (string, error) {
	var buf [6]byte
	if _, err := rand.Read(buf[:]); err != nil {
		return "", fmt.Errorf("read random bytes: %w", err)
	}
	return hex.EncodeToString(buf[:]), nil
}

// currentHeadSHA returns the current HEAD commit hash as a 40-char hex
// string. Mirrors review.currentHeadSHA — kept local to avoid taking a
// dependency on the review package.
func currentHeadSHA(ctx context.Context, repoRoot string) (string, error) {
	out, err := runGit(ctx, repoRoot, "rev-parse", "HEAD")
	if err != nil {
		return "", fmt.Errorf("git rev-parse HEAD: %w", err)
	}
	return strings.TrimSpace(out), nil
}

// wrapSilent applies the silent-error wrapper if it is non-nil. Mirrors
// review's pattern so tests can inject a passthrough.
func wrapSilent(fn func(error) error, err error) error {
	if fn == nil {
		return err
	}
	return fn(err)
}

// runGit runs `git <args>` in repoDir and returns stdout as a string. We
// keep a local copy rather than importing review's helper to avoid
// coupling cmd/entire/cli/investigate to cmd/entire/cli/review.
func runGit(ctx context.Context, repoRoot string, args ...string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = repoRoot
	var stderr strings.Builder
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		stderrTxt := strings.TrimSpace(stderr.String())
		if stderrTxt != "" {
			return "", fmt.Errorf("git %s: %w (stderr: %s)", args[0], err, stderrTxt)
		}
		return "", fmt.Errorf("git %s: %w", args[0], err)
	}
	return string(out), nil
}

// Package types — see reviewer.go for package-level rationale.
//
// sink.go defines the consumer-side abstractions for review runs:
// Sink (event consumer interface), RunSummary (post-run record),
// AgentRun (per-agent post-run data), and AgentStatus (terminal state enum).
package types

import "time"

// Sink consumes events from a review run. Sinks are passed to the
// orchestrator at construction time; selecting which sinks compose
// is the caller's job (TUI vs. non-TTY, synthesis on/off).
//
// Concurrency: AgentEvent and RunFinished are guaranteed to be invoked
// from a single goroutine — the orchestrator serializes calls even under
// multi-agent runs (CU8 fans events from N agents into one dispatch
// loop). Sinks need not internally synchronize.
//
// Sinks MUST NOT block. AgentEvent runs on the dispatch goroutine; a
// slow sink stalls the entire run and starves all other sinks.
type Sink interface {
	// AgentEvent is called for every event emitted by an agent's
	// process during the run. Events are delivered in-order within a
	// single agent; across agents (CU8 multi-agent) the orchestrator
	// serializes calls so sinks see one event at a time.
	AgentEvent(agent string, ev Event)

	// RunFinished is called once when the run terminates (cleanly,
	// failed, or cancelled). Sinks that only act post-run (DumpSink,
	// synthesis sink) implement only this method (with a no-op
	// AgentEvent).
	RunFinished(summary RunSummary)
}

// RunSummary is the post-run record passed to all sinks.
type RunSummary struct {
	StartedAt  time.Time
	FinishedAt time.Time

	// Cancelled is true iff the orchestrator's run context was cancelled
	// during the run (or before it started). For single-agent runs this
	// is equivalent to AgentRuns[0].Status == AgentStatusCancelled. Under
	// multi-agent runs (CU8), Cancelled means "the run as a whole was
	// cancelled" — individual AgentRuns may have other terminal states
	// if they finished before cancellation propagated.
	Cancelled bool

	AgentRuns []AgentRun
}

// AgentRun is per-agent post-run data.
type AgentRun struct {
	Name   string
	Status AgentStatus
	Tokens Tokens

	// Buffer accumulates the full event log per agent for post-hoc
	// rendering (DumpSink, TUI dump, synthesis).
	//
	// TODO(memory): At review lengths typical today (~100s of events,
	// ~few KB) this is fine. If profiling shows reviews regularly
	// exceed ~10MB of buffered events or ~10000 events, swap to a
	// token-budgeted ring or stream events to sinks incrementally
	// and drop the buffer.
	Buffer []Event

	StartedAt time.Time
	Duration  time.Duration
	Err       error
}

// AgentStatus is the terminal state for an agent.
type AgentStatus int

const (
	AgentStatusUnknown AgentStatus = iota
	AgentStatusSucceeded
	AgentStatusFailed
	AgentStatusCancelled
)

// String returns a human-readable status (used in dump output and TUI).
func (s AgentStatus) String() string {
	switch s {
	case AgentStatusUnknown:
		return "unknown"
	case AgentStatusSucceeded:
		return "succeeded"
	case AgentStatusFailed:
		return "failed"
	case AgentStatusCancelled:
		return "cancelled"
	default:
		return "unknown"
	}
}

// Package types defines the per-agent abstraction interfaces for `entire review`.
//
// AgentReviewer is the contract every supported agent (claude-code, codex,
// gemini-cli, future additions) implements in its own package. The orchestrator
// in cmd/entire/cli/review/run.go consumes this interface, never importing
// concrete agent packages — that's how new agents land as additive files
// without touching shared code.
//
// Events flow as a stream: implementations spawn the agent process, parse
// stdout into a sequence of typed Events (Started, AssistantText, ToolCall,
// Tokens, Finished, RunError), and surface them via Process.Events. Per-agent
// quirks (codex's chrome stripping, gemini's stdin requirement, claude's argv
// shape) are entirely encapsulated inside each agent's adapter — shared code
// only sees the cleaned event stream.
//
// Living in a subpackage (not the review root package) avoids import cycles:
// per-agent reviewers and the orchestrator both depend on these types
// without depending on each other.
package types

import "context"

// AgentReviewer drives a single agent's review run.
type AgentReviewer interface {
	// Name returns the agent's registry key (e.g., "claude-code", "codex",
	// "gemini-cli"). Stable identifier; do not change after release without
	// updating settings migration.
	Name() string

	// Start spawns the agent with the given run configuration. The returned
	// Process exposes streaming events via Events() and a Wait() that returns
	// when the process exits.
	//
	// Implementations MUST set the ENTIRE_REVIEW_* env vars on the spawned
	// child process (see cmd/entire/cli/review/env.go) so the agent's
	// lifecycle hooks adopt the session as a review session.
	//
	// Errors from Start indicate failure to construct or launch the process
	// (e.g., binary not on PATH at exec.Cmd.Start time, invalid argv). Once
	// Start returns nil, errors during the run flow through Process.Events
	// (as RunError) and Process.Wait.
	Start(ctx context.Context, run RunConfig) (Process, error)
}

// Process represents a running agent review.
type Process interface {
	// Events returns a channel that emits structured events as the agent
	// produces output. The channel is closed when the process exits — cleanly,
	// with error, or via context cancellation. Consumers should range over it.
	Events() <-chan Event

	// Wait blocks until the process exits and returns:
	//   - nil on clean exit (exit code 0)
	//   - ctx.Err() on cancellation
	//   - an error wrapping *exec.ExitError on non-zero exit
	//   - other error types for I/O or pipe failures
	//
	// Wait must be called exactly once per Process. It is safe to call Wait
	// after the Events channel has closed. Consumers must drain Events until
	// close before calling Wait; otherwise an implementation that forwards
	// parsed events from another goroutine may block while sending.
	Wait() error
}

// RunConfig is the immutable per-run configuration passed to AgentReviewer.Start.
//
// All fields are optional from a marshalling standpoint (zero value is valid),
// but Skills is typically non-empty in practice — it carries the skill
// invocations (e.g., "/pr-review-toolkit:review-pr") the configured agent
// should run.
type RunConfig struct {
	// PromptOverride, when non-empty, is the exact prompt sent to the agent.
	// It preserves settings.ReviewConfig.Prompt's existing verbatim-override
	// contract: configured skills are still recorded as structured metadata,
	// but they are not prepended to the prompt text.
	PromptOverride string

	// Skills are skill invocation strings passed to the agent verbatim.
	Skills []string

	// AlwaysPrompt is the per-agent always-prompt configured in settings.
	// Concatenated with Skills + PerRunPrompt + a scope clause to form the
	// composed agent prompt.
	AlwaysPrompt string

	// PerRunPrompt is optional textarea input from a single invocation.
	PerRunPrompt string

	// ScopeBaseRef is the git ref the review is scoped against (typically the
	// closest ancestor branch). Used to compose the scope clause and as the
	// base for `git diff` operations the agent may perform.
	ScopeBaseRef string

	// CheckpointContext is best-effort context derived from checkpoints in the
	// branch review scope. It is appended to generated prompts so every agent
	// can use checkpoint IDs, file summaries, and transcript lookup commands
	// while reviewing. PromptOverride remains verbatim and does not receive
	// this context.
	CheckpointContext string

	// StartingSHA is HEAD at invocation time, propagated to the lifecycle
	// hook via ENTIRE_REVIEW_STARTING_SHA so checkpoint metadata records
	// the commit that was reviewed.
	StartingSHA string
}

// Event is the sealed sum type emitted by Process.Events. The unexported
// isEvent method prevents external packages from adding event variants;
// adding a new event requires updating this file (and every consumer's
// type switch — that's intentional, since a new event variant is a contract
// change).
type Event interface{ isEvent() }

// Started signals the agent has begun the review. Adapters typically emit
// this once at the top of the event stream.
type Started struct{}

func (Started) isEvent() {}

// AssistantText is narrative output from the agent (the actual review
// response, not tool-call chrome or session metadata).
type AssistantText struct {
	Text string
}

func (AssistantText) isEvent() {}

// ToolCall reports a tool invocation by the agent. Args is an opaque
// adapter-defined string — typically JSON for agents that emit structured
// tool input (e.g., claude-code), or a single-line summary for those that
// don't (e.g., codex). Shared consumers should treat Args as display-only
// and not parse it; structured tool data is intentionally not part of this
// contract.
type ToolCall struct {
	Name string
	Args string
}

func (ToolCall) isEvent() {}

// Tokens reports cumulative token counts (running totals, not deltas).
// Adapters may emit multiple Tokens events during a run; each emission
// supersedes the prior, so consumers should overwrite (not sum) on receipt.
// Adapters that only receive aggregate shutdown totals should emit at most one
// final Tokens event rather than inventing deltas.
type Tokens struct {
	In  int
	Out int
}

func (Tokens) isEvent() {}

// Finished signals the agent has produced its final output and the event
// stream is about to end. Success indicates the agent self-reported a
// clean task completion. Success=false means the agent finished its event
// stream but signaled it did not complete the review task — distinct from
// process exit failure (which surfaces via Process.Wait, not as an event).
//
// Adapters typically emit this once at the bottom of the event stream,
// before the channel closes.
type Finished struct {
	Success bool
}

func (Finished) isEvent() {}

// RunError reports a non-fatal error during the run (e.g., hook failure,
// transient stream parse error). Fatal errors that stop the agent surface
// via Process.Wait, not as events.
type RunError struct {
	Err error
}

func (RunError) isEvent() {}

